//
//  PrimaryKey.swift
//  LiteRow
//

/// A table's primary key description. Generated by `@Table` from `@PrimaryKey` attributes.
public protocol PrimaryKeyProtocol: Sendable {
    /// The key value: the column's own type for a single-column key, or the generated
    /// `PrimaryKey` struct with one field per column for a composite key.
    associatedtype Key: Sendable

    /// The typed key columns as a pack: `(repeat Column<Root, each V>)`.
    associatedtype Columns: Sendable

    /// The key values as an unlabeled pack: `(repeat each V)`.
    associatedtype Values: Sendable

    /// The key columns in declaration order.
    static var columns: Columns { get }

    /// Number of columns in a key-only projection.
    static var size: Int32 { get }

    /// The key's values in column order.
    static func values(of key: Key) -> Values

    /// Reads a key from a key-only projection (positions follow `columns`, not the table layout).
    static func decode(_ row: borrowing Row, offset: Int32) throws(LiteRowError) -> Key
}

/// A table with a primary key.
public protocol PrimaryKeyTable: Table {
    associatedtype PrimaryKey: PrimaryKeyProtocol

    /// This row's key.
    var primaryKey: PrimaryKey.Key { get }
}

extension PrimaryKeyTable {
    /// A query for one row by primary key.
    ///
    /// - Parameter schema: As in `all(in:)`; `nil` uses the schema from `@Table`.
    public static func find<each V: SQLiteValue & Equatable>(
        _ key: PrimaryKey.Key,
        in schema: DatabaseFile? = nil
    ) -> some Query<Self>
    where PrimaryKey.Columns == (repeat Column<Self, each V>), PrimaryKey.Values == (repeat each V)
    {
        let columns = PrimaryKey.columns
        let values = PrimaryKey.values(of: key)
        return all(in: schema)
            .filter { table in
                CompoundExpression(of: Bool.self,
                                   op: .and,
                                   args: (repeat ColumnExpression(of: (each V).self,
                                                                  table: table,
                                                                  quotedColumn: (each columns).quotedName) == (each values)))
            }
            .limit(1)
            .query()
    }
}

extension Reader {
    /// Fetches a row by primary key; `nil` if there is none.
    public func fetchOne<T: PrimaryKeyTable, each V: SQLiteValue & Equatable>(
        _ table: T.Type,
        key: T.PrimaryKey.Key,
        in schema: DatabaseFile? = nil
    ) throws(LiteRowError) -> T?
    where T.PrimaryKey.Columns == (repeat Column<T, each V>), T.PrimaryKey.Values == (repeat each V)
    {
        try fetchOne(T.find(key, in: schema))
    }
}

/// A row consisting only of primary key columns.
public struct KeyRow<Root: PrimaryKeyTable>: RowDecodable {
    public let key: Root.PrimaryKey.Key

    @inlinable public static var width: Int32 { Root.PrimaryKey.size }

    @inlinable public init(_ row: borrowing Row, offset: Int32) throws(LiteRowError) {
        key = try Root.PrimaryKey.decode(row, offset: offset)
    }
}

// MARK: - Key projection

extension QueryBuilder where Output: PrimaryKeyTable {

    /// Projects onto the primary key column, fetching keys instead of rows.
    public func selectKey<V: SQLiteValue>() -> QueryBuilder<KeyRow<Output>, Source, Joined>
    where Source == Output, Output.PrimaryKey.Columns == Column<Output, V>
    {
        let projection = ColumnExpression<V, Output>(table: source, quotedColumn: Output.PrimaryKey.columns.quotedName)
        return .init(source: source, quotedSourceSchema: quotedSourceSchema, refs: refs, joins: joins,
                     projection: projection, predicates: predicates, groupBy: groupBy,
                     having: having, order: order, limit: limit, offset: offset,
                     isDistinct: isDistinct)
    }

    /// Same for a composite key, with columns in key order.
    public func selectKey<each V: SQLiteValue>() -> QueryBuilder<KeyRow<Output>, Source, Joined>
    where Source == Output, Output.PrimaryKey.Columns == (repeat Column<Output, each V>)
    {
        let columns = Output.PrimaryKey.columns
        let projected = (repeat ColumnExpression<each V, Output>(table: source, quotedColumn: (each columns).quotedName))
        return .init(source: source, quotedSourceSchema: quotedSourceSchema, refs: refs, joins: joins,
                     projection: CompoundExpression(of: Never.self, op: .coma, args: (repeat each projected)),
                     predicates: predicates, groupBy: groupBy,
                     having: having, order: order, limit: limit, offset: offset,
                     isDistinct: isDistinct)
    }
}
